// clshim: an OpenCL interposer for looking inside LiteRT's GPU accelerator
// (ML Drift) on Android. Installed as libOpenCL.so (and libOpenCL-pixel.so)
// in LD_LIBRARY_PATH; every entry point the vendor library exports is
// forwarded (tramp.S, generated by gen_tramp.py); these are wrapped:
//
//   clCreateProgramWithSource  -> $CLSHIM_DIR/pNNN.cl (the generated kernel source)
//   clBuildProgram             -> $CLSHIM_DIR/pNNN.opts (build options, build time)
//   clCreateKernel             -> kernel name / program id
//   clCreateCommandQueue*      -> adds CL_QUEUE_PROFILING_ENABLE when CLSHIM_PROFILE=1
//   clEnqueueNDRangeKernel     -> records kernel, global/local size and an event
//   clFinish / clWaitForEvents -> harvests completed events into per-kernel GPU time
//
// clshim_mark(label) (looked up by the bench with dlopen("libOpenCL.so") + dlsym)
// prints the per-kernel table for the interval since the previous mark and resets.
// The real library: $CLSHIM_REAL, else /vendor/lib64/libOpenCL.so, else the
// libOpenCL-pixel.so enableOpenCL()/loadOpenCLPointer() route.
#define _GNU_SOURCE
#include <dlfcn.h>
#include <pthread.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef int32_t cl_int;
typedef uint32_t cl_uint;
typedef uint64_t cl_ulong;
typedef cl_ulong cl_bitfield;
typedef cl_bitfield cl_command_queue_properties;
typedef intptr_t cl_queue_properties;
typedef void* cl_context;
typedef void* cl_device_id;
typedef void* cl_command_queue;
typedef void* cl_program;
typedef void* cl_kernel;
typedef void* cl_event;
typedef void* cl_platform_id;

#define CL_QUEUE_PROPERTIES 0x1093
#define CL_QUEUE_PROFILING_ENABLE (1 << 1)
#define CL_PROFILING_COMMAND_START 0x1282
#define CL_PROFILING_COMMAND_END 0x1283
#define CL_EVENT_COMMAND_EXECUTION_STATUS 0x11D3
#define CL_COMPLETE 0x0

extern void* clshim_real[];
extern const char* const clshim_names[];
extern const int clshim_n;

static pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER;
static void* real_lib;
static void* (*pixel_load)(const char*);
static const char* dir;
static int profile;
static FILE* logf;

static void* real_sym(const char* name) {
  void* p = NULL;
  if (real_lib) p = dlsym(real_lib, name);
  if (!p && pixel_load) p = pixel_load(name);
  return p;
}

__attribute__((constructor)) static void clshim_init(void) {
  dir = getenv("CLSHIM_DIR");
  if (!dir) dir = ".";
  profile = getenv("CLSHIM_PROFILE") && atoi(getenv("CLSHIM_PROFILE"));
  char path[512];
  snprintf(path, sizeof path, "%s/clshim.log", dir);
  logf = fopen(path, "a");
  if (!logf) logf = stderr;
  const char* want = getenv("CLSHIM_REAL");
  if (!want) want = "/vendor/lib64/libOpenCL.so";
  real_lib = dlopen(want, RTLD_NOW | RTLD_LOCAL);
  if (!real_lib) {
    fprintf(logf, "clshim: dlopen %s failed: %s; trying libOpenCL-pixel route\n", want, dlerror());
    void* px = dlopen("/vendor/lib64/libOpenCL-pixel.so", RTLD_NOW | RTLD_LOCAL);
    if (px) {
      void (*en)(void) = (void (*)(void))dlsym(px, "enableOpenCL");
      pixel_load = (void* (*)(const char*))dlsym(px, "loadOpenCLPointer");
      if (en) en();
    }
  }
  int missing = 0;
  for (int i = 0; i < clshim_n; ++i) {
    clshim_real[i] = real_sym(clshim_names[i]);
    if (!clshim_real[i]) ++missing;
  }
  fprintf(logf, "clshim: real=%s lib=%p pixel=%p profile=%d, %d/%d entry points missing\n", want, real_lib,
          (void*)pixel_load, profile, missing, clshim_n);
  fflush(logf);
}


static double now_ms(void) {
  struct timespec t;
  clock_gettime(CLOCK_MONOTONIC, &t);
  return t.tv_sec * 1e3 + t.tv_nsec * 1e-6;
}

// ---------------------------------------------------------------- programs/kernels
#define MAXP 4096
#define MAXK 8192
static struct { cl_program p; int id; } progs[MAXP];
static int nprogs, prog_seq;
static struct { cl_kernel k; char name[96]; int prog; } kernels[MAXK];
static int nkernels;

static int prog_id(cl_program p) {
  for (int i = nprogs - 1; i >= 0; --i)
    if (progs[i].p == p) return progs[i].id;
  return -1;
}

typedef cl_program (*pfn_cpws)(cl_context, cl_uint, const char**, const size_t*, cl_int*);
cl_program clCreateProgramWithSource(cl_context c, cl_uint n, const char** s, const size_t* l, cl_int* e) {
  pfn_cpws f = (pfn_cpws)real_sym("clCreateProgramWithSource");
  cl_program p = f(c, n, s, l, e);
  pthread_mutex_lock(&mu);
  int id = prog_seq++;
  if (nprogs < MAXP) { progs[nprogs].p = p; progs[nprogs].id = id; ++nprogs; }
  char path[512];
  snprintf(path, sizeof path, "%s/p%04d.cl", dir, id);
  FILE* o = fopen(path, "w");
  if (o) {
    for (cl_uint i = 0; i < n; ++i) fwrite(s[i], 1, l && l[i] ? l[i] : strlen(s[i]), o);
    fclose(o);
  }
  pthread_mutex_unlock(&mu);
  return p;
}

typedef cl_program (*pfn_cpwb)(cl_context, cl_uint, const cl_device_id*, const size_t*, const unsigned char**,
                               cl_int*, cl_int*);
cl_program clCreateProgramWithBinary(cl_context c, cl_uint n, const cl_device_id* d, const size_t* l,
                                     const unsigned char** b, cl_int* st, cl_int* e) {
  pfn_cpwb f = (pfn_cpwb)real_sym("clCreateProgramWithBinary");
  cl_program p = f(c, n, d, l, b, st, e);
  pthread_mutex_lock(&mu);
  int id = prog_seq++;
  if (nprogs < MAXP) { progs[nprogs].p = p; progs[nprogs].id = id; ++nprogs; }
  fprintf(logf, "program %d from binary (%zu bytes)\n", id, l ? l[0] : 0);
  pthread_mutex_unlock(&mu);
  return p;
}

typedef cl_int (*pfn_build)(cl_program, cl_uint, const cl_device_id*, const char*, void (*)(cl_program, void*),
                            void*);
cl_int clBuildProgram(cl_program p, cl_uint n, const cl_device_id* d, const char* opts,
                      void (*cb)(cl_program, void*), void* ud) {
  pfn_build f = (pfn_build)real_sym("clBuildProgram");
  double t = now_ms();
  cl_int r = f(p, n, d, opts, cb, ud);
  t = now_ms() - t;
  pthread_mutex_lock(&mu);
  int id = prog_id(p);
  char path[512];
  snprintf(path, sizeof path, "%s/p%04d.opts", dir, id);
  FILE* o = fopen(path, "w");
  if (o) { fprintf(o, "%s\nbuild %.1f ms status %d\n", opts ? opts : "", t, r); fclose(o); }
  pthread_mutex_unlock(&mu);
  return r;
}

typedef cl_kernel (*pfn_ck)(cl_program, const char*, cl_int*);
cl_kernel clCreateKernel(cl_program p, const char* name, cl_int* e) {
  pfn_ck f = (pfn_ck)real_sym("clCreateKernel");
  cl_kernel k = f(p, name, e);
  pthread_mutex_lock(&mu);
  if (nkernels < MAXK) {
    kernels[nkernels].k = k;
    snprintf(kernels[nkernels].name, sizeof kernels[nkernels].name, "%s", name);
    kernels[nkernels].prog = prog_id(p);
    ++nkernels;
  }
  pthread_mutex_unlock(&mu);
  return k;
}

static int kernel_idx(cl_kernel k) {
  for (int i = nkernels - 1; i >= 0; --i)
    if (kernels[i].k == k) return i;
  return -1;
}

// ---------------------------------------------------------------- queues
typedef cl_command_queue (*pfn_ccq)(cl_context, cl_device_id, cl_command_queue_properties, cl_int*);
cl_command_queue clCreateCommandQueue(cl_context c, cl_device_id d, cl_command_queue_properties p, cl_int* e) {
  pfn_ccq f = (pfn_ccq)real_sym("clCreateCommandQueue");
  if (profile) p |= CL_QUEUE_PROFILING_ENABLE;
  fprintf(logf, "clCreateCommandQueue props=0x%llx\n", (unsigned long long)p);
  return f(c, d, p, e);
}

typedef cl_command_queue (*pfn_ccqp)(cl_context, cl_device_id, const cl_queue_properties*, cl_int*);
cl_command_queue clCreateCommandQueueWithProperties(cl_context c, cl_device_id d, const cl_queue_properties* p,
                                                    cl_int* e) {
  pfn_ccqp f = (pfn_ccqp)real_sym("clCreateCommandQueueWithProperties");
  cl_queue_properties np[64];
  int n = 0, have = 0;
  for (; p && p[n] && n < 60; n += 2) {
    np[n] = p[n];
    np[n + 1] = p[n + 1];
    if (p[n] == CL_QUEUE_PROPERTIES) {
      have = 1;
      if (profile) np[n + 1] |= CL_QUEUE_PROFILING_ENABLE;
    }
    fprintf(logf, "clCreateCommandQueueWithProperties 0x%llx=0x%llx\n", (unsigned long long)p[n],
            (unsigned long long)p[n + 1]);
  }
  if (!have && profile) { np[n++] = CL_QUEUE_PROPERTIES; np[n++] = CL_QUEUE_PROFILING_ENABLE; }
  np[n] = 0;
  return f(c, d, np, e);
}

// ---------------------------------------------------------------- dispatch timing
typedef cl_int (*pfn_ndr)(cl_command_queue, cl_kernel, cl_uint, const size_t*, const size_t*, const size_t*, cl_uint,
                          const cl_event*, cl_event*);
typedef cl_int (*pfn_evinfo)(cl_event, cl_uint, size_t, void*, size_t*);
typedef cl_int (*pfn_rel)(cl_event);

#define MAXPEND 65536
static struct { cl_event ev; int k; size_t g[3], l[3]; int dim; } pend[MAXPEND];
static int npend;
#define MAXSTAT 4096
static struct {
  int k; size_t g[3], l[3];
  long long n; double ns;
} stat_[MAXSTAT];
static int nstat;
static double interval_ns;
static unsigned long long interval_first = ~0ull, interval_last;
static long long dispatches;

cl_int clEnqueueNDRangeKernel(cl_command_queue q, cl_kernel k, cl_uint dim, const size_t* off, const size_t* g,
                              const size_t* l, cl_uint nw, const cl_event* w, cl_event* ev) {
  pfn_ndr f = (pfn_ndr)real_sym("clEnqueueNDRangeKernel");
  cl_event mine = NULL;
  cl_event* use = ev;
  if (profile && !ev) use = &mine;
  cl_int r = f(q, k, dim, off, g, l, nw, w, use);
  pthread_mutex_lock(&mu);
  ++dispatches;
  if (profile && r == 0 && npend < MAXPEND) {
    cl_event e = *use;
    if (ev) ((cl_int(*)(cl_event))real_sym("clRetainEvent"))(e);
    pend[npend].ev = e;
    pend[npend].k = kernel_idx(k);
    pend[npend].dim = dim;
    for (int i = 0; i < 3; ++i) {
      pend[npend].g[i] = i < (int)dim ? g[i] : 1;
      pend[npend].l[i] = (l && i < (int)dim) ? l[i] : 0;
    }
    ++npend;
  } else if (mine) {
    ((pfn_rel)real_sym("clReleaseEvent"))(mine);
  }
  pthread_mutex_unlock(&mu);
  return r;
}

// Harvest completed events (caller holds mu). all=1 harvests everything (after a finish).
static void harvest(int all) {
  pfn_evinfo pi = (pfn_evinfo)real_sym("clGetEventProfilingInfo");
  pfn_evinfo ei = (pfn_evinfo)real_sym("clGetEventInfo");
  pfn_rel rel = (pfn_rel)real_sym("clReleaseEvent");
  int keep = 0;
  for (int i = 0; i < npend; ++i) {
    cl_int st = -1;
    ei(pend[i].ev, CL_EVENT_COMMAND_EXECUTION_STATUS, sizeof st, &st, NULL);
    if (st != CL_COMPLETE && !(all && st < 0)) {
      if (!all) { pend[keep++] = pend[i]; continue; }
    }
    cl_ulong a = 0, b = 0;
    if (pi(pend[i].ev, CL_PROFILING_COMMAND_START, sizeof a, &a, NULL) == 0 &&
        pi(pend[i].ev, CL_PROFILING_COMMAND_END, sizeof b, &b, NULL) == 0 && b >= a) {
      int s = 0;
      for (; s < nstat; ++s)
        if (stat_[s].k == pend[i].k && !memcmp(stat_[s].g, pend[i].g, sizeof stat_[s].g) &&
            !memcmp(stat_[s].l, pend[i].l, sizeof stat_[s].l))
          break;
      if (s == nstat && nstat < MAXSTAT) {
        stat_[s].k = pend[i].k;
        memcpy(stat_[s].g, pend[i].g, sizeof stat_[s].g);
        memcpy(stat_[s].l, pend[i].l, sizeof stat_[s].l);
        stat_[s].n = 0;
        stat_[s].ns = 0;
        ++nstat;
      }
      if (s < nstat) { stat_[s].n++; stat_[s].ns += (double)(b - a); }
      interval_ns += (double)(b - a);
      if (a < interval_first) interval_first = a;
      if (b > interval_last) interval_last = b;
    }
    rel(pend[i].ev);
  }
  npend = all ? 0 : keep;
}

typedef cl_int (*pfn_fin)(cl_command_queue);
cl_int clFinish(cl_command_queue q) {
  cl_int r = ((pfn_fin)real_sym("clFinish"))(q);
  if (profile) { pthread_mutex_lock(&mu); harvest(0); pthread_mutex_unlock(&mu); }
  return r;
}

typedef cl_int (*pfn_wfe)(cl_uint, const cl_event*);
cl_int clWaitForEvents(cl_uint n, const cl_event* e) {
  cl_int r = ((pfn_wfe)real_sym("clWaitForEvents"))(n, e);
  if (profile) { pthread_mutex_lock(&mu); harvest(0); pthread_mutex_unlock(&mu); }
  return r;
}

// CLSHIM_NOCB=1 hides cl_khr_command_buffer (extension string and entry points)
// so the accelerator enqueues kernels directly and each one gets an event.
static int nocb(void) {
  static int v = -1;
  if (v < 0) v = getenv("CLSHIM_NOCB") && atoi(getenv("CLSHIM_NOCB"));
  return v;
}

static void strip_ext(char* s, const char* ext) {
  char* p;
  size_t n = strlen(ext);
  while ((p = strstr(s, ext)) != NULL && (p[n] == ' ' || p[n] == 0 || p[n] == '_')) {
    // remove the whole token (up to the next space)
    char* e = p;
    while (*e && *e != ' ') ++e;
    while (*e == ' ') ++e;
    memmove(p, e, strlen(e) + 1);
  }
}

#define CL_DEVICE_EXTENSIONS 0x1030
#define CL_PLATFORM_EXTENSIONS 0x0904
typedef cl_int (*pfn_info)(void*, cl_uint, size_t, void*, size_t*);
static cl_int ext_info(const char* fn, void* obj, cl_uint param, cl_uint ext_param, size_t sz, void* val,
                       size_t* ret) {
  pfn_info f = (pfn_info)real_sym(fn);
  if (param != ext_param) return f(obj, param, sz, val, ret);
  size_t need = 0;
  cl_int r = f(obj, param, 0, NULL, &need);
  if (r) return r;
  char* buf = malloc(need + 1);
  r = f(obj, param, need, buf, NULL);
  if (r) { free(buf); return r; }
  buf[need] = 0;
  static int logged[2];
  if (!logged[ext_param == CL_DEVICE_EXTENSIONS]++) fprintf(logf, "%s extensions: %s\n", fn, buf);
  if (!nocb()) {
    free(buf);
    return f(obj, param, sz, val, ret);
  }
  strip_ext(buf, "cl_khr_command_buffer");
  size_t n = strlen(buf) + 1;
  if (ret) *ret = n;
  if (val) {
    if (sz < n) { free(buf); return -30; /* CL_INVALID_VALUE */ }
    memcpy(val, buf, n);
  }
  free(buf);
  return 0;
}

cl_int clGetDeviceInfo(void* d, cl_uint param, size_t sz, void* val, size_t* ret) {
  return ext_info("clGetDeviceInfo", d, param, CL_DEVICE_EXTENSIONS, sz, val, ret);
}

cl_int clGetPlatformInfo(void* p, cl_uint param, size_t sz, void* val, size_t* ret) {
  return ext_info("clGetPlatformInfo", p, param, CL_PLATFORM_EXTENSIONS, sz, val, ret);
}

typedef void* (*pfn_gefa)(cl_platform_id, const char*);
void* clGetExtensionFunctionAddressForPlatform(cl_platform_id p, const char* name) {
  void* r = ((pfn_gefa)real_sym("clGetExtensionFunctionAddressForPlatform"))(p, name);
  if (nocb() && strstr(name, "CommandBuffer")) r = NULL;
  if (nocb() && strstr(name, "clCommand") == name) r = NULL;
  fprintf(logf, "ext fn %s -> %p\n", name, r);
  return r;
}

static int cmp_stat(const void* a, const void* b) {
  double x = ((const typeof(stat_[0])*)a)->ns, y = ((const typeof(stat_[0])*)b)->ns;
  return x < y ? 1 : x > y ? -1 : 0;
}

// Print the per-kernel table since the previous mark (divided by `runs`), then reset.
void clshim_mark(const char* label, int runs) {
  pthread_mutex_lock(&mu);
  harvest(0);
  if (runs < 1) runs = 1;
  qsort(stat_, nstat, sizeof stat_[0], cmp_stat);
  FILE* o = logf;
  fprintf(o, "== %s: %lld dispatches, kernel GPU time %.3f ms/run (sum), first-start..last-end %.3f ms/run over %d runs, %d pending\n",
          label, dispatches / runs, interval_ns / 1e6 / runs,
          interval_last > interval_first ? (interval_last - interval_first) / 1e6 / runs : 0.0, runs, npend);
  for (int s = 0; s < nstat; ++s) {
    int k = stat_[s].k;
    fprintf(o, "%9.3f ms %5.1f%% x%-5lld p%04d %-40s g=%zux%zux%zu l=%zux%zux%zu\n", stat_[s].ns / 1e6 / runs,
            100.0 * stat_[s].ns / (interval_ns > 0 ? interval_ns : 1), stat_[s].n / runs,
            k >= 0 ? kernels[k].prog : -1, k >= 0 ? kernels[k].name : "?", stat_[s].g[0], stat_[s].g[1],
            stat_[s].g[2], stat_[s].l[0], stat_[s].l[1], stat_[s].l[2]);
  }
  fflush(o);
  nstat = 0;
  interval_ns = 0;
  interval_first = ~0ull;
  interval_last = 0;
  dispatches = 0;
  pthread_mutex_unlock(&mu);
}
